// Modification requested: make it photorealistic
const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.bias = -0.0001;

const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);

const rimLight = new THREE.PointLight(0xaad6ff, 0.45, 22);
rimLight.position.set(-4, 3, -5);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.32), keyLight, fillLight, rimLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(12, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -1.5;
floor.receiveShadow = true;
scene.add(floor);

const workersGroup = new THREE.Group();
scene.add(workersGroup);

const bodyMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  roughness: 0.2,
  metalness: 0.1,
  clearcoat: 0.8,
  clearcoatRoughness: 0.1
});

const jointMaterial = new THREE.MeshStandardMaterial({
  color: 0x2a3b4c,
  roughness: 0.4,
  metalness: 0.8
});

const coreMaterial = new THREE.MeshPhysicalMaterial({
  color: 0x00d4ff,
  emissive: 0x00a8cc,
  emissiveIntensity: 0.8,
  roughness: 0.1,
  metalness: 0,
  transmission: 0.6,
  thickness: 0.5
});

const upholsteryMat = new THREE.MeshPhysicalMaterial({
  color: 0x4a5568,
  roughness: 0.9,
  metalness: 0.1,
  clearcoat: 0.1
});

const frameMat = new THREE.MeshStandardMaterial({
  color: 0x2a3b4c,
  roughness: 0.3,
  metalness: 0.9
});

const workers = [];
const workerCount = 3;
const radius = 3;

for (let i = 0; i < workerCount; i++) {
  const angle = (i / workerCount) * Math.PI * 2;
  const x = Math.cos(angle) * radius;
  const z = Math.sin(angle) * radius;

  const worker = new THREE.Group();
  worker.position.set(x, 0.55, z);
  worker.lookAt(0, 0, 0);

  const bodyGeo = new THREE.CylinderGeometry(0.4, 0.5, 1.2, 32);
  const body = new THREE.Mesh(bodyGeo, bodyMaterial);
  body.position.y = 0.6;
  body.castShadow = true;
  body.receiveShadow = true;
  worker.add(body);

  const coreGeo = new THREE.SphereGeometry(0.25, 32, 32);
  const core = new THREE.Mesh(coreGeo, coreMaterial);
  core.position.set(0, 0.8, 0.35);
  worker.add(core);

  const headGeo = new THREE.SphereGeometry(0.35, 32, 32);
  const head = new THREE.Mesh(headGeo, bodyMaterial);
  head.position.y = 1.5;
  head.castShadow = true;
  worker.add(head);

  const visorGeo = new THREE.CapsuleGeometry(0.08, 0.25, 4, 16);
  const visor = new THREE.Mesh(visorGeo, coreMaterial);
  visor.rotation.z = Math.PI / 2;
  visor.position.set(0, 1.5, 0.28);
  worker.add(visor);

  const createArm = (side) => {
    const armGroup = new THREE.Group();
    armGroup.position.set(side * 0.5, 1.1, 0);

    const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.15, 16, 16), jointMaterial);
    armGroup.add(shoulder);

    const upperArm = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.6, 16), bodyMaterial);
    upperArm.position.y = -0.3;
    armGroup.add(upperArm);

    const elbow = new THREE.Mesh(new THREE.SphereGeometry(0.12, 16, 16), jointMaterial);
    elbow.position.y = -0.6;
    armGroup.add(elbow);

    const lowerArm = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.06, 0.5, 16), bodyMaterial);
    lowerArm.position.y = -0.85;
    armGroup.add(lowerArm);

    const hand = new THREE.Mesh(new THREE.BoxGeometry(0.15, 0.2, 0.1), jointMaterial);
    hand.position.y = -1.1;
    armGroup.add(hand);

    return armGroup;
  };

  const rightArm = createArm(1);
  const leftArm = createArm(-1);
  worker.add(rightArm);
  worker.add(leftArm);

  worker.userData = {
    phase: i * (Math.PI * 2 / workerCount),
    arms: [rightArm, leftArm],
    core: core
  };

  workers.push(worker);
  workersGroup.add(worker);

  const chair = new THREE.Group();
  chair.position.set(x, 0, z);
  chair.lookAt(0, 0, 0);

  const seatMesh = new THREE.Mesh(
    new THREE.CylinderGeometry(0.4, 0.4, 0.12, 32),
    upholsteryMat
  );
  seatMesh.position.y = 0.5;
  seatMesh.castShadow = true;
  seatMesh.receiveShadow = true;
  chair.add(seatMesh);

  const backMesh = new THREE.Mesh(
    new THREE.BoxGeometry(0.5, 0.7, 0.1),
    upholsteryMat
  );
  backMesh.position.set(0, 0.9, -0.35);
  backMesh.rotation.x = -0.1;
  backMesh.castShadow = true;
  chair.add(backMesh);

  const spine = new THREE.Mesh(
    new THREE.CylinderGeometry(0.04, 0.04, 0.4, 16),
    frameMat
  );
  spine.position.set(0, 0.7, -0.38);
  chair.add(spine);

  [-1, 1].forEach(side => {
    const armGroup = new THREE.Group();
    armGroup.position.set(side * 0.45, 0.8, 0);

    const armPost = new THREE.Mesh(
      new THREE.CylinderGeometry(0.03, 0.03, 0.3, 16),
      frameMat
    );
    armPost.position.y = -0.15;
    armGroup.add(armPost);

    const armPad = new THREE.Mesh(
      new THREE.BoxGeometry(0.08, 0.04, 0.3),
      upholsteryMat
    );
    armPad.position.z = 0.1;
    armGroup.add(armPad);

    chair.add(armGroup);
  });

  const column = new THREE.Mesh(
    new THREE.CylinderGeometry(0.06, 0.06, 0.5, 16),
    frameMat
  );
  column.position.y = 0.25;
  chair.add(column);

  const baseGroup = new THREE.Group();
  baseGroup.position.y = 0.02;
  for (let k = 0; k < 5; k++) {
    const legAngle = (k / 5) * Math.PI * 2;
    const leg = new THREE.Mesh(
      new THREE.BoxGeometry(0.06, 0.05, 0.45),
      frameMat
    );
    leg.position.set(Math.sin(legAngle) * 0.225, 0, Math.cos(legAngle) * 0.225);
    leg.rotation.y = legAngle;
    leg.castShadow = true;
    baseGroup.add(leg);

    const wheel = new THREE.Mesh(
      new THREE.CylinderGeometry(0.05, 0.05, 0.04, 16),
      new THREE.MeshStandardMaterial({ color: 0x1a202c })
    );
    wheel.rotation.z = Math.PI / 2;
    wheel.position.set(Math.sin(legAngle) * 0.42, -0.05, Math.cos(legAngle) * 0.42);
    baseGroup.add(wheel);
  }
  chair.add(baseGroup);

  workersGroup.add(chair);
}

const hubGeo = new THREE.IcosahedronGeometry(0.6, 2);
const hubMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  roughness: 0.1,
  metalness: 0.1,
  transmission: 0.9,
  thickness: 1.0,
  emissive: 0x00d4ff,
  emissiveIntensity: 0.2
});
const hub = new THREE.Mesh(hubGeo, hubMaterial);
hub.position.y = 0.8;
scene.add(hub);

const particleGeo = new THREE.SphereGeometry(0.04, 8, 8);
const particleMat = new THREE.MeshBasicMaterial({ color: 0x00d4ff, transparent: true, opacity: 0.8 });
const particles = [];

for (let i = 0; i < 60; i++) {
  const particle = new THREE.Mesh(particleGeo, particleMat);
  particle.userData = {
    workerIndex: i % workerCount,
    progress: Math.random(),
    speed: 0.3 + Math.random() * 0.4,
    offset: new THREE.Vector3((Math.random() - 0.5) * 0.5, 0.5 + Math.random() * 0.8, (Math.random() - 0.5) * 0.5)
  };
  particles.push(particle);
  scene.add(particle);
}

const beams = [];
for (let i = 0; i < workerCount; i++) {
  const curve = new THREE.QuadraticBezierCurve3(new THREE.Vector3(), new THREE.Vector3(), new THREE.Vector3());
  const tubeGeo = new THREE.TubeGeometry(curve, 20, 0.02, 8, false);
  const tubeMat = new THREE.MeshBasicMaterial({ color: 0x00d4ff, transparent: true, opacity: 0.3 });
  const tube = new THREE.Mesh(tubeGeo, tubeMat);
  tube.userData = { startWorker: i, endWorker: (i + 1) % workerCount };
  beams.push(tube);
  scene.add(tube);
}

camera.position.set(6, 4, 8);
camera.lookAt(0, 0.5, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  workersGroup.rotation.y = t * 0.08;

  workers.forEach((worker, index) => {
    const data = worker.userData;
    worker.position.y = 0.55 + Math.sin(t * 1.5 + data.phase) * 0.03;

    const pulse = 0.8 + Math.sin(t * 2 + data.phase) * 0.3;
    data.core.material.emissiveIntensity = pulse;

    const armAngle = Math.sin(t * 1.2 + data.phase) * 0.3;
    data.arms.forEach((arm, armIndex) => {
      arm.rotation.z = armAngle * (armIndex === 0 ? 1 : -1);
      arm.rotation.x = Math.sin(t * 0.8 + data.phase) * 0.2;
    });
  });

  hub.rotation.x = t * 0.2;
  hub.rotation.y = t * 0.3;
  hub.material.emissiveIntensity = 0.2 + Math.sin(t * 3) * 0.1;

  particles.forEach(particle => {
    const data = particle.userData;
    data.progress += data.speed * 0.01;

    if (data.progress > 1) {
      data.progress = 0;
      data.workerIndex = (data.workerIndex + 1) % workerCount;
    }

    const startWorker = workers[data.workerIndex];
    const endWorker = workers[(data.workerIndex + 1) % workerCount];

    const startPos = startWorker.position.clone().add(data.offset);
    const endPos = endWorker.position.clone().add(data.offset);
    const center = new THREE.Vector3(0, 1.2, 0);

    const oneMinusT = 1 - data.progress;
    particle.position.x = oneMinusT * oneMinusT * startPos.x + 2 * oneMinusT * data.progress * center.x + data.progress * data.progress * endPos.x;
    particle.position.y = oneMinusT * oneMinusT * startPos.y + 2 * oneMinusT * data.progress * center.y + data.progress * data.progress * endPos.y;
    particle.position.z = oneMinusT * oneMinusT * startPos.z + 2 * oneMinusT * data.progress * center.z + data.progress * data.progress * endPos.z;
  });

  beams.forEach(beam => {
    const start = workers[beam.userData.startWorker];
    const end = workers[beam.userData.endWorker];
    const mid = new THREE.Vector3(0, 1.5, 0);

    const curve = new THREE.QuadraticBezierCurve3(
      start.position.clone().add(new THREE.Vector3(0, 0.8, 0)),
      mid,
      end.position.clone().add(new THREE.Vector3(0, 0.8, 0))
    );

    beam.geometry.dispose();
    beam.geometry = new THREE.TubeGeometry(curve, 20, 0.02, 8, false);
    beam.material.opacity = 0.2 + Math.sin(t * 2 + beam.userData.startWorker) * 0.1;
  });

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  renderer.render(scene, camera);
}

animate();

