let phase = 0;
let time = 0;
const trails = [];

function addTrail(pos, color, size = 0.15) {
    const g = new THREE.SphereGeometry(size, 8, 8);
    const m = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: 0.6 });
    const mesh = new THREE.Mesh(g, m);
    mesh.position.copy(pos);
    scene.add(mesh);
    trails.push({ mesh: mesh, life: 50 });
}

function reset() {
    phase = 0;
    time = 0;
    proton.position.set(-10, 0, 0);
    proton.visible = true;
    boronGroup.visible = true;
    protonLabel.visible = true;
    boronLabel.visible = true;
    subLabel.material.opacity = 0;

    alphas.forEach(a => {
        a.mesh.visible = false;
        a.active = false;
    });

    burst.scale.set(1, 1, 1);
    burst.material.opacity = 0;
    glowSprite.scale.set(0, 0, 0);
    reactorLight.intensity = 0;
    energyLight.intensity = 0;

    trails.forEach(t => {
        scene.remove(t.mesh);
        t.mesh.geometry.dispose();
        t.mesh.material.dispose();
    });
    trails.length = 0;
}

function update() {
    time++;
    reactorGroup.rotation.y += 0.005;

    if (phase === 0) {
        proton.position.x += 0.12;
        if (time % 2 === 0) addTrail(proton.position, 0xff0044, 0.2);

        if (proton.position.x > -1.5) {
            phase = 1;
            proton.visible = false;
            boronGroup.visible = false;
            protonLabel.visible = false;
            boronLabel.visible = false;
        }
    } else if (phase === 1) {
        reactorLight.intensity = 4;
        energyLight.intensity = 3;
        burst.material.opacity = 0.9;
        glowSprite.scale.set(12, 12, 12);
        glowSprite.material.opacity = 1;

        const angles = [0, 2.094, 4.189];
        alphas.forEach((a, i) => {
            a.mesh.visible = true;
            a.mesh.position.set(0, 0, 0);
            const speed = 0.25;
            a.velocity.set(
                Math.cos(angles[i]) * speed,
                (Math.random() - 0.5) * 0.15,
                Math.sin(angles[i]) * speed
            );
            a.active = true;
        });

        phase = 2;
    } else if (phase === 2) {
        burst.material.opacity *= 0.95;
        burst.scale.multiplyScalar(1.03);
        reactorLight.intensity *= 0.98;
        energyLight.intensity *= 0.97;
        glowSprite.scale.multiplyScalar(0.97);

        alphas.forEach((a, i) => {
            if (a.active) {
                a.mesh.position.add(a.velocity);
                a.velocity.multiplyScalar(0.992);
                if (time % 2 === 0) addTrail(a.mesh.position, 0xffdd00, 0.25);
                a.mesh.rotation.x += 0.1;
            }
        });

        if (time > 150) {
            subLabel.material.opacity = Math.min(1, subLabel.material.opacity + 0.03);
        }

        if (time > 350) reset();
    }

    for (let i = trails.length - 1; i >= 0; i--) {
        const t = trails[i];
        t.life--;
        t.mesh.material.opacity = (t.life / 50) * 0.6;
        t.mesh.scale.multiplyScalar(0.96);
        if (t.life <= 0) {
            scene.remove(t.mesh);
            trails.splice(i, 1);
        }
    }
}

function animate() {
    requestAnimationFrame(animate);
    update();
    renderer.render(scene, camera);
}

