function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  workersGroup.rotation.y = t * 0.08;

  workers.forEach((worker, index) => {
    const data = worker.userData;
    worker.position.y = Math.sin(t * 1.5 + data.phase) * 0.15;

    const pulse = 0.8 + Math.sin(t * 2 + data.phase) * 0.3;
    data.core.material.emissiveIntensity = pulse;

    const armAngle = Math.sin(t * 1.2 + data.phase) * 0.3;
    data.arms.forEach((arm, armIndex) => {
      arm.rotation.z = armAngle * (armIndex === 0 ? 1 : -1);
      arm.rotation.x = Math.sin(t * 0.8 + data.phase) * 0.2;
    });
  });

  hub.rotation.x = t * 0.2;
  hub.rotation.y = t * 0.3;
  hub.material.emissiveIntensity = 0.2 + Math.sin(t * 3) * 0.1;

  particles.forEach(particle => {
    const data = particle.userData;
    data.progress += data.speed * 0.01;

    if (data.progress > 1) {
      data.progress = 0;
      data.workerIndex = (data.workerIndex + 1) % workerCount;
    }

    const startWorker = workers[data.workerIndex];
    const endWorker = workers[(data.workerIndex + 1) % workerCount];

    const startPos = startWorker.position.clone().add(data.offset);
    const endPos = endWorker.position.clone().add(data.offset);
    const center = new THREE.Vector3(0, 1.2, 0);

    const oneMinusT = 1 - data.progress;
    particle.position.x = oneMinusT * oneMinusT * startPos.x + 2 * oneMinusT * data.progress * center.x + data.progress * data.progress * endPos.x;
    particle.position.y = oneMinusT * oneMinusT * startPos.y + 2 * oneMinusT * data.progress * center.y + data.progress * data.progress * endPos.y;
    particle.position.z = oneMinusT * oneMinusT * startPos.z + 2 * oneMinusT * data.progress * center.z + data.progress * data.progress * endPos.z;
  });

  beams.forEach(beam => {
    const start = workers[beam.userData.startWorker];
    const end = workers[beam.userData.endWorker];
    const mid = new THREE.Vector3(0, 1.5, 0);

    const curve = new THREE.QuadraticBezierCurve3(
      start.position.clone().add(new THREE.Vector3(0, 0.8, 0)),
      mid,
      end.position.clone().add(new THREE.Vector3(0, 0.8, 0))
    );

    beam.geometry.dispose();
    beam.geometry = new THREE.TubeGeometry(curve, 20, 0.02, 8, false);
    beam.material.opacity = 0.2 + Math.sin(t * 2 + beam.userData.startWorker) * 0.1;
  });

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  renderer.render(scene, camera);
}

