            a.mesh.visible = true;
            a.mesh.position.set(0, 0, 0);
            const speed = 0.25;
            a.velocity.set(
                Math.cos(angles[i]) * speed,
                (Math.random() - 0.5) * 0.15,
                Math.sin(angles[i]) * speed
            );
            a.active = true;
        });

        phase = 2;
    } else if (phase === 2) {
        burst.material.opacity *= 0.95;
        burst.scale.multiplyScalar(1.03);
        reactorLight.intensity *= 0.98;
        energyLight.intensity *= 0.97;
        glowSprite.scale.multiplyScalar(0.97);

        alphas.forEach((a, i) => {
            if (a.active) {
                a.mesh.position.add(a.velocity);
                a.velocity.multiplyScalar(0.992);
                if (time % 2 === 0) addTrail(a.mesh.position, 0xffdd00, 0.25);
                a.mesh.rotation.x += 0.1;
