        });

        if (time > 150) {
            subLabel.material.opacity = Math.min(1, subLabel.material.opacity + 0.03);
        }

        if (time > 350) reset();
    }

    for (let i = trails.length - 1; i >= 0; i--) {
        const t = trails[i];
        t.life--;
        t.mesh.material.opacity = (t.life / 50) * 0.6;
